struct block_device *get_block_device(dev_t dev, struct super_block *sb) {
    struct block_device *bdev = NULL;
    int flags = FMODE_READ | FMODE_WRITE | FMODE_EXCL;

    bdev = bdget(dev);
    if (!bdev) {
        printk(KERN_ERR "Failed to get block device for dev %d\n", dev);
        return NULL;
    }

    if (bdev->bd_openers) {
        bdput(bdev);
        printk(KERN_ERR "Block device for dev %d already in use\n", dev);
        return NULL;
    }

    if (bdev->bd_super) {
        bdput(bdev);
        printk(KERN_ERR "Block device for dev %d already has a filesystem\n", dev);
        return NULL;
    }

    if (sb) {
        sb->s_bdev = bdev;
        sb->s_dev = dev;
    }

    if (bdev->bd_disk && bdev->bd_disk->fops->open) {
        int err = bdev->bd_disk->fops->open(bdev, flags);
        if (err) {
            bdput(bdev);
            printk(KERN_ERR "Failed to open block device for dev %d: %d\n", dev, err);
            return NULL;
        }
    }

    bdev->bd_openers++;
    return bdev;
}

