#include <linux/fs.h>
#include <linux/genhd.h>
#include <linux/kernel.h>

struct block_device *get_block_device(dev_t dev, struct super_block *sb) {
    struct block_device *bdev;
    int ret;

    bdev = open_by_devnum(dev, FMODE_READ | FMODE_WRITE | FMODE_EXCLUSIVE);
    if (IS_ERR(bdev)) {
        pr_err("Failed to open block device for dev %d:%d\n", MAJOR(dev), MINOR(dev));
        return NULL;
    }

    ret = blkdev_get(bdev, FMODE_READ | FMODE_WRITE | FMODE_EXCLUSIVE, sb);
    if (ret) {
        pr_err("Failed to get block device for dev %d:%d\n", MAJOR(dev), MINOR(dev));
        put_disk(bdev->bd_disk);
        return NULL;
    }

    return bdev;
}
